        if isinstance(timestamp, datetime):
            self.timestamp = timestamp
            self.tz = tz
        else:
            self.timestamp = datetime.fromtimestamp(timestamp, tz)
            self.tz = tz

    def __repr__(self):
        return f"{self.timestamp.strftime('%Y-%m-%d %H:%M:%S%Z') if self.tz else self.timestamp.strftime('%Y-%m-%d %H:%M:%S')} tz={self.tz}"

