def pop_u16(self):
    """
    Remove the last two bytes of data, returning them as a big-endian
    16-bit unsigned integer.
    """
    if len(self.data) < 2:
        raise ValueError("Not enough data to pop_u16")
    byte1, byte2 = self.data[-2:]
    self.data = self.data[:-2]
    return (int.from_bytes(bytes1, byteorder='big') << 8) | int.from_bytes(bytes2, byteorder='big')

