            MessageType.ERROR,
            None,
            dehydration_hooks=self.dehydration_hooks,
            hydration_hooks=self.hydration_hooks,
        )
        if hasattr(self, 'before_transaction_aborted'):
            self.before_transaction_aborted()

    def stop(self):
