def round_half_to_even(n):
    """
    Round half to even.

    :param n:
    :return:
    """
    if not isinstance(n, (int, float)):
        raise TypeError("Input must be a number")
    if n % 1 == 0:  # if n is an integer
        return int(n)
    fractional_part = n - int(n)
    if fractional_part >= 0.5:
        return int(n + 0.5)
    elif fractional_part < -0.5:
        return int(n - 0.5)
    else:
        return int(n)

def round_half_to_even(n):
    """
    Rounding half to even with Python's built-in round function.

    :param n:
    :return:
    """
    # determine if the last digit is even or odd
    if int(abs(n) % 10) % 2 == 0:
        return round(n)
    # if the last digit is odd, add 0.5 to the number if it's positive or subtract 0.5 if it's negative
    else:
        return round(n + 0.5) if n >= 0 else round(n - 0.5)

