def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if not hasattr(self, 'values'):
        self.values = np.zeros_like(self.edges)
    if coord < self.edges[0] or coord > self.edges[-1]:
        return
    idx = np.searchsorted(self.edges, coord) - 1
    if idx >= 0 and idx < len(self.edges) - 1:
        self.values[idx] += weight

def fill(self, coord, weight=1):
        if self.min_coord <= coord <= self.max_coord:
            if coord in self.bins:
                index = self.bins.index(coord)
                self.values[index] += weight
            else:
                self.bins.append(coord)
                self.values.append(weight)

