def validate_value(self, value, **_):
    """Validate the given value according to the regex defined in the attribute self.regex.

    Args:
        value: the string to validate

    Raises:
        ValidationError: in case of any validation error.
    """
    if not value:
        raise ValidationError("Value cannot be empty", "ValidationError")

    if not isinstance(value, str):
        raise ValidationError("Value must be a string", "ValidationError")

    if not self.regex.match(value):
        raise ValidationError("Value does not match the regular expression", "ValidationError")

