def get_logical_path_map(inventory, version):
        if version not in inventory:
            raise ValueError(f"Version {version} is not in the inventory.")
        files_contents_map = {}
        current_version = version
        while current_version:
            repo_logical_path = inventory[current_version]
            current_version = inventory.get(current_version['parent_version'])
            if not current_version:
                break
            content_files = inventory[current_version]['content_files']
            logical_path = repo_logical_path.replace("$VERSION$", version)
            if logical_path in files_contents_map:
                files_contents_map[logical_path].add(content_files)
            else:
                files_contents_map[logical_path] = {content_files}
        return files_contents_map

