    for logical_path in inventory.logical_paths():
        files_in_version = set()
        for file_path, version_data in inventory.version_files(version):
            content_files = file_path.replace(os.sep, '/').split('/')
            if content_files[0] == logical_path:
                files_in_version.add('.'.join(content_files))
