    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_path_map = {}

    for path, state in inventory.items():
        logical_path = path.split('/')[-2]  # Get the logical path by splitting and taking the last two components
        if logical_path in logical_path_map:
            logical_path_map[logical_path].add(path)  # Add the file to the set
            # Check if this version includes content references that are also present in later versions
            content_files = self.get_content_files(state['reference'])
            for file in content_files:
                if file in logical_path_map[logical_path]:
                    logical_path_map[logical_path].add(file)  # Add duplicate files to the set

        else:
            content_files = self.get_content_files(state['reference'])
            logical_path_map[logical_path] = set(content_files)  # Create a set with the file

    return logical_path_map

