def add_rendition(self, lang, file_path):
    """
    {
        "original": "artigo02.pdf",
        "en": "artigo02-en.pdf",
    }
    """
    if lang not in self.renditions:
        self.renditions[lang] = {}

    input_file = os.path.join(self.original_dir, file_path)
    output_file = os.path.join(self.output_dir_for_lang, f"artigo02-{lang}.pdf")

    if not os.path.exists(input_file):
        raise FileNotFoundError(f"Input file {input_file} does not exist.")

    if os.path.exists(output_file):
        raise FileExistsError(f"Output file {output_file} already exists.")

    os.system(f"convert {input_file} {output_file}")

def add_rendition(self, lang, file_path):
    qualified_filename = os.path.join(self.output_dir, file_path)
    ensure_dir_exists(qualified_filename)

    for target_lang, target_file_path in self.renditions[lang].items():
        if target_file_path:
            file_suffix = target_file_path[-4:]
            if target_file_path.endswith(".txt"):
                ensure_dir_exists(os.path.join(self.output_dir, target_lang))
                with open(os.path.join(self.output_dir, target_lang, file_path), 'w') as output_file:
                    output_file.writelines(self.translated_docs[lang][file_path].split('\n'))
                file_path = f"{quality}.{file_suffix}"
            else:
                file_path = target_file_path

            output_file = os.path.join(self.output_dir, lang, file_path)
            with io.open(output_file, "wb") as output:
