    """
    {
        "original": "artigo02.pdf",
        "en": "artigo02-en.pdf",
    }
    """
    output_dir = os.path.join(self._output_dir, lang)
    if not os.path.exists(output_dir):
        os.makedirs(output_dir)

    output_name = os.path.join(output_dir, os.path.basename(file_path))
    shutil.copy2(file_path, output_name)
    return output_name

