def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    if not isinstance(validate_objects, bool):
        raise TypeError('validate_objects must be a boolean.')
    if not isinstance(check_digests, bool):
        raise TypeError('check_digests must be a boolean.')
    if not isinstance(show_warnings, bool):
        raise TypeError('show_warnings must be a boolean.')

    # iterate over the hierarchy structure
    for obj in self.hierarchy.get_hierarchy_objects():
        num_objects += 1
        if validate_objects:
            # validate each object
            if self.validate_object(obj):
                good_objects += 1
        else:
            good_objects += 1

    # check hashes if centrally computed and display warnings
    if check_digests:
        for obj in self.hierarchy.get_hierarchy_objects():
            num_objects += 1
            if obj.requires_hash_computing():
                hash_value = obj.compute_hash()
                if hash_value != obj.get_hash():
                    if show_warnings:
                        self.logger.warning(f"DB hash of {obj.get_identity()} has changed from {obj.get_hash()} to {hash_value}.")
                    return False

    return num_objects, good_objects

