def validate_version_inventories(self, version_dirs):
    for i in range(1, len(version_dirs)):
        current_dir = f"version_{i}"
        if not os.path.exists(current_dir):
            raise ValueError(f"Expected version directory: {current_dir}")

        with open(f"{current_dir}/inventory", 'r') as f:
            inventory = f.read()

        with open(f"version_1/inventory", 'r') as f:
            root_inventory = f.read()

        for line in inventory.split('\n'):
            if line.startswith('!'):
                continue

            item = line.split()
            if len(item) < 3:
                raise ValueError(f'Incorrect inventory format in version {current_dir}: {line}')

            digest = item[2]
            root_digest = None

            lines = root_inventory.split('\n')
            for line in lines:
                if line.startswith('!'):
                    continue

                item = line.split()
                if len(item) < 4:
                    raise ValueError(f'Incorrect root inventory format: {line}')

                digest = item[3]
                if item[1] == digest:
                    root_digest = digest
                    break

            if not root_digest:
                raise ValueError(f'Content digest {digest} does not match any in root inventory')

            with open(f"{current_dir}/content", 'r') as f:
                content = f.read()

            if content != root_inventory:
                raise ValueError(f'Content in version {current_dir} does not match that in root inventory')

