def amend_bzparams(self, params, bug_ids):
    """
    Amend the Bugzilla params

    >>> bz_params = {'reponame': 'awesome-repo'}
    >>> bug_ids = [123456, 789012]
    >>> bz = Bugsy()
    >>> bz.amend_bzparams(bz_params, bug_ids)
    """
    for bug_id in bug_ids:
        if str(bug_id) in params:
            result = self.request('bug/%s' % bug_id, 'PUT',
                                  json={'bug': {'params': params[str(bug_id)]}})

