def bash_completion():
    """
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    """

    # Define completion types
    completion_types = {
        'option': 1,
        'argument': 2
    }

    # Get all registered commands and their options/arguments
    command_info = get_command_parameters()

    # Generate bash completion options
    bash_options = []
    for name, command in command_info.items():
        for param_name, param in command.items():
            completer_info = []
            type_id = completion_types.get(param.param_type_name, -1)
            print_type = '<>' * 16
            print(f'                 {type_id}: "{param.param_type_name}" {ftype}')
            completer_info.append(f'                      <[{name}.{param_name}]>')
            if param.help:
                completer_info.append(f'            {param.help}')
            if param.param_type_name == 'option':
                option = get_name(param)
                same_dest = [
                    get_name(p) for p in capabilities if p.name == param.name
                ]
                if same_dest:
                    option = "({})".format(" ".join(same_dest)) + option
                if param.is_flag:
