def _replace_register(flow_params, register_number, register_value):
    """
    Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number
    """
    if isinstance(register_value, str):
        register_value = flow_params.get(register_value, None)
    if isinstance(register_value, dict):
        if 'value' in register_value:
            register_value['value'] = flow_params.get(register_value['value'], None)
        if 'amount' in register_value:
            register_value['amount'] = flow_params.get(register_value['amount'], None)
    if isinstance(register_value, list):
        if 'value' in register_value:
            register_value['value'] = flow_params.get(register_value['value'], None)
        if 'amount' in register_value:
            register_value['amount'] = flow_params.get(register_value['amount'], None)
    elif register_value is not None:
        raise ValueError(f"Invalid value for register: {register_value}")
    return register_value

for old_var, new_var in flow_params.items():
        if old_var == register_value:
            flow_params[register_number] = new_var

