def prepare_repository_from_archive(archive_path: str, filename: Optional[str] = None, tmp_path: Union[PosixPath, str] = "/tmp") -> str:
    if not os.path.exists(archive_path):
        raise ValueError(f"Archive {archive_path} does not exist")

    # Unpack the archive into a temporary directory
    with subprocess.Popen(['tar', '-xzf', archive_path], cwd=tmp_path, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True) as process:
        output, error = process.communicate()
        if process.returncode != 0:
            raise subprocess.CalledProcessError(process.returncode, output, error)

    # Get the name of the unpacked directory
    unpack_dir =Path(tmp_path) /Path(archive_path).stem

    # Find the file with the specified filename
    for root, dirs, files in os.walk(unpack_dir):
        for file in files:
            if filename and file == filename:
                file_path = Path(root) / file
                url = create_repo_url(file_path, header)
                return url

    raise ValueError(f"No file named {filename} found in the unpacked directory")

