    globs = []
    for pattern in find_paths:
        if not re.match(r'\*\*', pattern):
            globs.append(pattern)
        else:
            glob_parts = pattern.split('*')
            for i in range(len(glob_parts)):
                glob_parts[i] = '**' + glob_parts[i]
            globs.append('*'.join(glob_parts))
    return globs

