def subprocess_run_helper(func, *args, timeout=None, extra_env=None):
    args = list(args)
    args.insert(0, "python")
    args.insert(1, "-c")
    args.insert(2, f"from importlib.machinery import ModuleSpec; from importlib.util import module_from_spec\n" 
                 f"spec = ModuleSpec('{func.__module__}', None)\ndef main(*args):\n    import sys\n    sys.modules['' + func.__name__] = spec.loader.exec_module(spec)\n    return {func.__name__}(*args)")
    if extra_env is not None:
        args.extend((f"{key}={value}" for key, value in extra_env.items()))
    result = subprocess.run(args, stdout=subprocess.PIPE, stderr=subprocess.PIPE, input=b'', timeout=timeout)
    if  result.returncode != 0:
        raise subprocess.CalledProcessError(result.returncode, result.stdout, result.stderr)
    return result.stdout.decode().strip()

def subprocess_run_helper(func, *args, timeout, extra_env=None):
    """
    Run a function in a sub-process.

    Parameters
    ----------
    func : function
        The function to be run.  It must be in a module that is importable.
    *args : str
        Any additional command line arguments to be passed in
        the first argument to ``subprocess.run``.
    extra_env : dict[str, str]
        Any additional environment variables to be set for the subprocess.
    """
    logging.basicConfig(level=DEBUG)

    def log_wrap(func, logger):
        def wrapper(*args, **kwargs):
            try:
                ret = func(*args, **kwargs)
            finally:
                if getattr(ret, 'stderr', None):
                    logger.warn(ret.stderr)
            return ret
        return wrapper

    func = log_wrap(func, logging.getLogger())

    try:
        ret = run(*args, env=extra_env, timeout=timeout)
    except TimeoutExpired:
        logger.warn('Timeout while trying to run function')
    else:
        # Log the output of the function
        if ret.stdout:
            logger.info('Function output:\n{}'.format(ret.stdout))
        if ret.stderr:
            logger.warn('Function stderr:\n{}'.format(ret.stderr))

    return ret

