def isoparse(self, dt_str):
    try:
        if isinstance(dt_str, str):
            dt_str = dt_str.strip()
            # Ignore timezone information
            if dt_str[-1] == 'Z':
                dt_str = dt_str[:-1].replace('Z', '+00:00')
            elif re.search(r"[+-]\d{2}:\d{2}", dt_str):
                dt_str += '+00:00'

            # Handle Moscow timezone
            if re.match(r"Moscow\]", dt_str):
                dt_str = re.sub(r"Moscow\]", r"Europe/Moscow", dt_str)

            parser = Parser().parse(dt_str)
            if isinstance(parser, str):
                return datetime.strptime(parser, ISO8601_UNICODE_FORMAT)
            elif isinstance(parser, dto.date):
                return parser
            elif isinstance(parser, dto.time):
                return datetime.combine(dto.date.today(), parser)
            elif isinstance(parser, dto.datetime):
                return parser
            else:
                raise ValueError("Invalid date format")
        else:
            raise TypeError("Input must be a string")
    except ValueError as e:
        raise ValueError("Error parsing ISO-8601 datetime string: {}".format(e))

