def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """

    if request.content_type != "application/x-www-form-urlencoded":
        return False

    params = request.POST
    if "client_secret" not in params and "token" not in params:
        return False

    return True

def identify_matrix_request(request):
    # Check if the 'host' header contains 'matrix.org'
    if not request.headers.get('host').endswith('.matrix.org'):
        return False

    # Check if the 'Content-Type' header contains the string 'application/x-matrix-chat'
    if request.headers.get('content-type') != 'application/x-matrix-chat':
        return False

    # If 'user_id' and 'room_id' are present, it's a Matrix request
    return all(k in request.headers for k in ['user_id', 'room_id'])

