def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    # Helper method to check if a path exists
    def path_exists(path):
        import os
        return os.path.exists(path)

    # Helper method to read the content of a file
    def read_file_content(file_path):
        with open(file_path, 'r') as file:
            return file.read()

    # Helper method to process the include directive
    def process_includeDirective(node, path):
        if node.name == 'include':
            included_path = node.value
            if path_exists(included_path):
                content = read_file_content(included_path)
                node.parent.insert(content, node)
            else:
                raise FileNotFoundError(f"Included file '{included_path}' not found")

    # Recursively process all nodes in the dictionary
    def recursive_process_dict(node):
        if node.type == 'dictionary':
            for key, value in iteritems(node.value):
                recursive_process_dict(value)
                if isinstance(value, dict) and 'include' in value:
                    process_includeDirective(value, node.path)
        elif node.type == 'section':
            for key, value in iteritems(node.value):
                recursive_process_dict(value)
                if isinstance(value, dict) and 'include' in value:
                    process_includeDirective(value, node.path)

    # Start processing the dictionary at the top level
    recursive_process_dict(parser_dict)

def _include_groups(self, parser_dict):
        """Resolves the include dict directive in the spec files. """

        def resolve_include(group_name, spec_data):
            if group_name is None or group_name == 'default':
                return spec_data
            if group_name == 'parent':
                return self._include_groups(spec_data['parent'])
            for group in spec_data.get('groups', []):
                if group['include'] == group_name:
                    return group
            raise ValueError(f'Group "{group_name}" not found in spec files')

        if 'include_groups' in parser_dict:
            for group_info in parser_dict['include_groups']:
                include_path = group_info.get('path')
                include_target = group_info.get('target')
                include_type = group_info.get('type', 'include')

                with open(include_path, 'r') as file:
                    include_content = file.read()

                if include_type == 'include':
                    resolved_spec = resolve_include(include_target, yaml.safe_load(include_content))
                    parser_dict['content'] += resolved_spec['content']
                elif include_type == 'merge':
                    import yaml
                    content_dict = yaml.safe_load(include_content)
                    for key, value in iteritems(content_dict):
                        parser_dict[key] = content_dict[key]

        return parser_dict

def _include_groups(self, parser_dict):
        """Resolves the include dict directive in the spec files. """
        for section, content in iteritems(parser_dict):
            if 'included_section' in content:
                if section in self.parser_parts:
                    continue
                self.parser_parts[section] = self.parser_dict[self.parser_parts[content['included_section']]]['settings']
                del self.parser_dict[section]

