def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                    spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    public_name = spec_option.get('public_name', None)
    name_suffix = spec_option.get('name_suffix', '')

    if public_name:
        public_name = public_name + name_suffix

    arg_type_name = spec_option.get('arg_type_name', None)
    if arg_type_name:
        arg_type_name = arg_type_name + name_suffix

    input_type = spec_option['input_type']
    optional = spec_option.get('optional', False)

    description = spec_option.get('description', '')

    args = []

    if input_type == 'STRING':
        if spec_option.get('password', False):
            args.append('Arguments.Type.Password')
        else:
            args.append('Arguments.Type.String')
    elif input_type == 'INTEGER':
        args.append('Arguments.Type.Integer')
    elif input_type == 'BOOLEAN':
        args.append('Arguments.Type.Boolean')
    elif input_type == 'LIST':
        args.append('Arguments.Type.List')
    else:
        raise ValueError(f"Unsupported input type: {input_type}")

    if spec_option.get('min_length', None) is not None:
        args.append(f'Arguments.Functionality.LengthMin({spec_option["min_length"]})')

    if spec_option.get('max_length', None) is not None:
        args.append(f'Arguments.Functionality.LengthMax({spec_option["max_length"]})')

    options = spec_option.get('options', [])
    for option in options:
        if option['name'] == option_name:
            if option.get('propagation', None) is not None:
                args.append('Arguments.Functionality.Authorization')
