def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # add global variables to avoid global keyword
    config = self.config

    for param in values_dict:
        # convert based on the parser specified
        if parser_name in config['global']:
            if 'map' in config['global'][parser_name]:
                if param in config['global'][parser_name]['map']:
                    parser_type = config['global'][parser_name]['map'][param]
                    values_dict[param] = config['global'][parser_name]['map'][param](values_dict[param])
        else:
            parser_type = self.get_parser(parser_name).type
            values_dict[param] = parser_type(values_dict[param])

